import puppeteer from "puppeteer-core"

const base = process.argv[2] || "http://127.0.0.1:8765"
const browser = await puppeteer.launch({
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  headless: true,
  args: ["--no-sandbox", "--disable-gpu", "--hide-scrollbars"]
})
const page = await browser.newPage()
const errors = []
page.on("pageerror", (err) => errors.push(String(err)))
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text())
})

async function shot(name, hash, opts = {}) {
  await page.setViewport({ width: opts.w || 1440, height: opts.h || 900, deviceScaleFactor: 1 })
  await page.goto(`${base}/${hash}`, { waitUntil: "load" })
  await new Promise((r) => setTimeout(r, opts.wait || 120))
  if (opts.click) {
    await page.click(opts.click)
    await new Promise((r) => setTimeout(r, 200))
  }
  if (opts.fill) {
    for (const [sel, val] of Object.entries(opts.fill)) {
      await page.focus(sel)
      await page.type(sel, val, { delay: 1 })
    }
    await new Promise((r) => setTimeout(r, 80))
  }
  await page.screenshot({ path: `screenshots/${name}.jpg`, type: "jpeg", quality: 76, fullPage: !!opts.full })
  console.log("shot", name)
}

import fs from "fs"
fs.mkdirSync("screenshots", { recursive: true })

await shot("01-home", "#home")
await shot("02-moves", "#moves")
await shot("03-here", "#here/shame")
await shot("04-near", "#near")
await shot("05-practice", "#practice/joke", { click: ".btn" })
await shot("06-far", "#far")
await shot("07-words", "#words")
await shot("08-card", "#card")
await shot("09-crisis", "#crisis")
await shot("10-home-mobile", "#home", { w: 390, h: 844 })
await shot("11-words-filled", "#words", {
  fill: {
    "textarea[data-field=fact]": "I made a joke about your work in front of everyone.",
    "textarea[data-field=own]": "I wanted the laugh, but I knew it was the sore place.",
    "textarea[data-field=hear]": "What was the worst part of it for you?",
    "textarea[data-field=one]": "Next time I will leave you out of it."
  }
})

console.log("ERRORS", errors)
await browser.close()

